import React from 'react';

const Hero = () => {
  return (
    <section className="bg-white py-16 md:py-24">
      <div className="container mx-auto flex flex-col md:flex-row items-center justify-between px-4 gap-8">
        <div className="hero-content text-center md:text-left md:w-1/2">
          <h1 className="text-4xl md:text-5xl lg:text-6xl font-extrabold text-primary-blue leading-tight mb-4">
            Stag.io: Your Career Future Starts Here.
          </h1>
          <p className="text-lg md:text-xl text-text-grey mb-8 max-w-lg mx-auto md:mx-0">
            A leading platform connecting university students with exceptional professional internship opportunities.
          </p>
          <div className="flex flex-col sm:flex-row justify-center md:justify-start gap-4">
            <button className="btn btn-primary text-lg px-8 py-3">Find an Internship</button>
            <button className="btn btn-secondary text-lg px-8 py-3">Post an Offer</button>
          </div>
        </div>
        <div className="hero-image md:w-1/2 mt-10 md:mt-0 flex justify-center">
          {/* Replace with your actual image or SVG for a dynamic work environment */}
          <img
            src="https://via.placeholder.com/600x400/007bff/ffffff?text=Dynamic+Work+Environment"
            alt="Dynamic Work Environment or Learning Students"
            className="rounded-lg shadow-xl max-w-full h-auto"
          />
        </div>
      </div>
    </section>
  );
};

export default Hero;
